			fasta_column_name = "gs-sample_name"
			gisaid_status_df = status_df[~status_df["gisaid_accession_epi_isl_id"].str.contains("EPI_ISL_", na=False)].copy()
			gisaid_status_df = gisaid_status_df[["gs-sample_name"]]
